/** Local, injected memory persistence and transport. ECDSA assertions are
 * generated by the existing explicit LAB authenticator, never human keys.
 */
import test from 'node:test';
import assert from 'node:assert/strict';
import {webcrypto,createHash} from 'node:crypto';
import {creaMotorPosse} from '../tooling/node0/posse/motor-posse.mjs';
import {signaAmbWebAuthn} from '../src/sections/tractors/nucli/aprovacio.js';
import {creaAutenticadorSimulat} from './helpers/autenticadorSimulat.js';
import {jsonCanonic} from '../src/sections/tractors/nucli/canonic.js';

const H='a'.repeat(64),BRIDGE='00000000-0000-4000-8000-000000000001',AUTHOR='10000000-0000-4000-8000-000000000001';
const ACTOR='https://mastodont.cat/users/depoble',AT=Date.parse('2026-11-18T10:00:00.000Z');
const REF={tenantId:'ac3bec76-255b-5ca2-8886-28fcceab4267',sectionId:'mur',id:'20000000-0000-4000-8000-000000000001'};
const clone=v=>structuredClone(v),hash=v=>createHash('sha256').update(v).digest('hex');
async function fixture({enabled=true,withdrawal=true,signed=true}={}){
  const auth=await creaAutenticadorSimulat({subtle:webcrypto.subtle});
  const context={},events=[],journals=new Map();let clock=AT,session=1,revokedAt=null,anchor=null;
  const faults={append:null,committedAppend:null,publish:false,ack:false,lateSession:false,lateCancel:null,mediaPending:false,expireOnIntent:false,revokeOnIntent:false,invalidAt:null,invalidMode:null,cancelControl:null};
  const counts={publishes:0,withdraws:0,preflights:0,uploads:0};
  const invalidate=stage=>{if(faults.invalidAt!==stage)return;
    if(faults.invalidMode==='expiry')clock=AT+120001;
    if(faults.invalidMode==='session')session++;
    if(faults.invalidMode==='key')revokedAt=new Date(clock).toISOString();
    if(faults.invalidMode==='cancel')faults.cancelControl.abort();
  };
  const bridge={id:BRIDGE,configRevision:'1',remoteAccountIdentity:ACTOR,policyProofSha256:H,
    linkedAuthors:[{kind:'entity',id:AUTHOR,enabled:true}],policy:{excludeCommercial:true},defaultTags:[]};
  let source={recordId:REF,recordRevision:'1',visibility:'public',canonicalUrl:'https://socdepoble.org/mur/prova',title:'Prova pública',summary:'Resum públic',tags:[]};
  let prepared=null,claim=null;
  const journal={read:async k=>clone(journals.get(k)??[]),append:async(k,event,{expectedHead})=>{
    const list=journals.get(k)??[],last=list.at(-1),head=last?{seq:last.seq,hash:last.hash}:{seq:0,hash:null};
    if(JSON.stringify(head)!==JSON.stringify(expectedHead))throw Object.assign(Error('CAS'),{code:'POSSE_TRAY_CAS_CHANGED'});
    if(faults.append===event.state)throw Error('LAB append failed');
    const copy=clone(event);list.push(copy);journals.set(k,list);events.push('journal:'+event.state);
    if(event.state==='dispatching'&&faults.expireOnIntent)clock=AT+120000;
    if(event.state==='dispatching'&&faults.revokeOnIntent)revokedAt=new Date(clock).toISOString();
    if(faults.committedAppend===event.state)throw Error('LAB committed ACK lost');
    return{committed:true,head:{seq:copy.seq,hash:copy.hash}};
  }};
  const repository={loadBridge:async()=>clone(bridge),loadRecord:async()=>clone(source),
    resolveEditorialProvenance:async()=>({authorKind:'entity',authorId:AUTHOR,proofSha256:H,commercial:false}),
    savePrepared:async value=>{prepared={...prepared,...clone(value),preparedId:'prepared-1'};return clone(prepared);},
    loadPrepared:async()=>clone(prepared),listPrepared:async()=>prepared?[clone(prepared)]:[],
    claimConfirmed:async()=>{
      if(claim?.state==='published')return clone(claim);
      if(claim?.state==='indeterminate')return{state:'indeterminate'};
      claim={state:'claimed',leaseId:'lease-1',quotaReserved:true,approvedSnapshot:clone(prepared.snapshot),operation:'create',externalStatusId:null,mediaId:claim?.mediaId??null};events.push('raw:claim');invalidate('claim');return clone(claim);
    },startDispatch:async({stage})=>{events.push('raw:dispatch');invalidate('marker:'+stage);return{authorized:true};},
    complete:async data=>{claim={state:'published',externalStatusId:data.externalStatusId,externalUrl:data.externalUrl};Object.assign(prepared,claim,{publishedHash:prepared.draftHash});},
    markIndeterminate:async()=>{claim={state:'indeterminate'};},releaseUnsent:async()=>{claim=null;},
    readPublicMedia:async()=>{invalidate('media-read');return{bytes:new Uint8Array([1,2,3]),mimeType:'image/png'};},
    saveMedia:async({mediaId})=>{claim.mediaId=mediaId;},releaseMediaPending:async()=>{claim.state='media-pending';prepared.state='media-pending';}}
  const transport={requiredScopes:()=>['write:statuses'],preflight:async()=>{counts.preflights++;invalidate('preflight');return{accountIdentity:ACTOR,scopes:['write:statuses'],certificationId:H};},
    publishStatus:async()=>{counts.publishes++;assert.equal(events.includes('journal:dispatching')||!signed,true);if(faults.publish)throw Error('LAB lost response');
      if(faults.lateSession)session++;
      faults.lateCancel?.abort();return{id:'900',url:'https://mastodont.cat/@depoble/900',accountIdentity:ACTOR};},validateResult:r=>r.accountIdentity===ACTOR,
    uploadMedia:async()=>{counts.uploads++;return{id:'50',ready:!faults.mediaPending};},getMedia:async()=>({id:'50',ready:!faults.mediaPending})};
  const withdrawalAdapter={send:async({receipt})=>{counts.withdraws++;assert.equal(events.at(-1),'journal:dispatching');return{withdrawn:true,...receipt};},verifyAck:async()=>!faults.ack};
  const options={repository,authorizeBridge:async supplied=>({allowed:supplied===context,actorProof:H}),certificaArticle:async({canonicalUrl})=>({ok:true,url:canonicalUrl,articleSha256:H}),
    transportForBridge:async()=>transport,publishingEnabled:enabled,now:()=>clock};
  if(signed)options.safataConformitat={journal,claus:async()=>auth.claus.map(k=>({...k,revokedAt})),origen:auth.origen,rpId:auth.rpId,subtle:webcrypto.subtle,
    captureContext:()=>{const captured=session;return()=>{if(session!==captured)throw new DOMException('LAB session changed','AbortError');};},
    anchorFor:async()=>anchor,withdrawal:withdrawal?withdrawalAdapter:null};
  const motor=creaMotorPosse(options);
  const prepare=()=>motor.prepare({bridgeId:BRIDGE,recordId:REF},context);
  const ref=head=>({bridgeId:BRIDGE,preparedId:'prepared-1',expectedHead:head});
  const sign=registre=>signaAmbWebAuthn({registre,credencial:auth.clau.credencial,credentials:auth.credentials,rpId:auth.rpId,subtle:webcrypto.subtle});
  const approve=async(state,action='publish')=>{const input={...ref(state.head),action},request=await motor.preparaAprovacio(input,context);
    const aprovacio=await sign(request.registre);return motor.aprova({...input,aprovacio},context);};
  const publish=async()=>{const p=await prepare(),a=await approve(p.conformitat);return motor.publish(ref(a.head),context);};
  return{motor,context,prepare,ref,sign,approve,publish,counts,events,journals,journal,faults,auth,options,
    setTime:ms=>{clock=ms;},setSource:patch=>{source={...source,...patch};},setBridge:patch=>Object.assign(bridge,patch),
    revokeKey:at=>{revokedAt=at;},setAnchor:a=>{anchor=a;},changeSession:()=>session++};
}

test('actual motor opt-in: signed preparation, publication, signed withdrawal and body-free Tombstone preserve all history',async()=>{
  const f=await fixture(),p=await f.prepare();assert.equal(p.conformitat.state,'prepared');assert.equal(f.counts.preflights,0);
  assert.equal('rawPublish'in f.motor,false);assert.equal('motor'in f.motor,false);
  await assert.rejects(f.motor.publish(f.ref(p.conformitat.head),f.context),e=>e.code==='POSSE_TRAY_APPROVAL_REQUIRED');
  const a=await f.approve(p.conformitat),published=await f.motor.publish(f.ref(a.head),f.context);
  assert.equal(published.state,'published');assert.equal(f.counts.publishes,1);
  const revoke=await f.approve(published,'revoke'),revoked=await f.motor.revoca(f.ref(revoke.head),f.context);
  assert.equal(revoked.state,'revoked');assert.equal(f.counts.withdraws,1);
  assert.deepEqual(Object.keys(revoked.tombstone).sort(),['@context','deleted','formerType','id','type']);
  assert.equal(revoked.tombstone.type,'Tombstone');assert.equal(JSON.stringify(revoked.tombstone).includes('Resum públic'),false);
  const list=[...f.journals.values()][0];assert.deepEqual(list.map(e=>e.state),['prepared','approved','dispatching','published','approved','dispatching','revoked']);
  assert.equal((await f.motor.listPrepared({bridgeId:BRIDGE},f.context))[0].conformitat.state,'revoked');
  assert.ok(Object.isFrozen(revoked.binding));assert.ok(Object.isFrozen(revoked.tombstone));
});

test('default legacy motor remains compatible; signed mode disabled refuses every publication before transport',async()=>{
  const legacy=await fixture({signed:false}),p=await legacy.prepare();
  assert.equal((await legacy.motor.publish({bridgeId:BRIDGE,bridgeRevision:p.bridgeRevision,preparedId:p.preparedId,recordRevision:p.recordRevision,draftHash:p.draftHash,confirm:true},legacy.context)).state,'published');
  const f=await fixture({enabled:false}),row=await f.prepare();await assert.rejects(f.motor.publish(f.ref(row.conformitat.head),f.context),e=>e.code==='POSSE_PUBLISH_DISABLED');assert.equal(f.counts.preflights,0);
});

test('real signature rejects text confirmation, changed action/binding/HEAD, forged proof, expiry and revoked key',async()=>{
  const f=await fixture(),p=await f.prepare(),input={...f.ref(p.conformitat.head),action:'publish'},request=await f.motor.preparaAprovacio(input,f.context),good=await f.sign(request.registre);
  for(const extra of [{aprovacio:{...good,nivell:'confirmacio'}},{aprovacio:{...good,empremta:'sha256:'+H}},
    {aprovacio:{...good,prova:{...good.prova,signatura:good.prova.signatura.slice(0,-2)+'AA'}}},{expectedHead:{seq:1,hash:H}},{preparedId:'other'},
    {aprovacio:{...good,nonce:'AQEBAQEBAQEBAQEBAQEBAQ'}}])await assert.rejects(f.motor.aprova({...input,aprovacio:good,...extra},f.context));
  f.setTime(AT+120000);await assert.rejects(f.motor.aprova({...input,aprovacio:good},f.context),e=>e.code==='POSSE_TRAY_APPROVAL_INVALID');
  f.setTime(AT);f.revokeKey(new Date(AT).toISOString());await assert.rejects(f.motor.aprova({...input,aprovacio:good},f.context),e=>e.code==='POSSE_TRAY_KEY_REVOKED');
  assert.equal(f.counts.publishes,0);
});

test('journal tamper, forged approval, ordering and truncation fail closed against an external anchor',async()=>{
  const f=await fixture(),p=await f.prepare(),approved=await f.approve(p.conformitat),key=[...f.journals.keys()][0],saved=clone(f.journals.get(key));
  f.setAnchor(approved.head);f.journals.set(key,saved.slice(0,1));
  await assert.rejects(f.motor.listPrepared({bridgeId:BRIDGE},f.context),e=>e.code==='POSSE_TRAY_ANCHOR_ABSENT');
  f.setAnchor(null);
  for(const mutation of [e=>{e[1].binding.draftHash=H;},e=>{e.reverse();},e=>{e[1].approval.nivell='confirmacio';
    const body=clone(e[1]);delete body.hash;e[1].hash=hash(jsonCanonic(body));}]){
    const changed=clone(saved);mutation(changed);f.journals.set(key,changed);await assert.rejects(f.motor.listPrepared({bridgeId:BRIDGE},f.context));
  }
  f.journals.set(key,saved);assert.equal((await f.motor.listPrepared({bridgeId:BRIDGE},f.context))[0].conformitat.state,'approved');
  const forged=clone(saved);forged[1].approval.prova.signatura='A'+forged[1].approval.prova.signatura.slice(1);
  const body=clone(forged[1]);delete body.hash;forged[1].hash=hash(jsonCanonic(body));f.journals.set(key,forged);
  await assert.rejects(f.motor.listPrepared({bridgeId:BRIDGE},f.context),e=>e.code==='POSSE_TRAY_SIGNATURE_INVALID');
});

test('CAS concurrent publication and replay cannot dispatch twice; stale source/account/policy revoke approvals',async()=>{
  const f=await fixture(),p=await f.prepare(),approved=await f.approve(p.conformitat),request=f.ref(approved.head);
  const results=await Promise.allSettled([f.motor.publish(request,f.context),f.motor.publish(request,f.context)]);
  assert.equal(results.filter(x=>x.status==='fulfilled').length,1);assert.equal(f.counts.publishes,1);
  await assert.rejects(f.motor.publish(request,f.context));assert.equal(f.counts.publishes,1);
  for(const change of [x=>x.setSource({recordRevision:'2'}),x=>x.setBridge({configRevision:'2'}),x=>x.setBridge({remoteAccountIdentity:'https://mastodont.cat/users/other'})]){
    const g=await fixture(),row=await g.prepare(),a=await g.approve(row.conformitat);change(g);
    await assert.rejects(g.motor.publish(g.ref(a.head),g.context));assert.equal(g.counts.publishes,0);
  }
});

test('append refusal happens before dispatch; lost post-ACK append remains indeterminate without retries',async()=>{
  const f=await fixture(),p=await f.prepare(),a=await f.approve(p.conformitat);f.faults.append='dispatching';
  await assert.rejects(f.motor.publish(f.ref(a.head),f.context));assert.equal(f.counts.publishes,0);assert.equal(f.counts.preflights,0);
  f.faults.append='published';await assert.rejects(f.motor.publish(f.ref(a.head),f.context),e=>e.code==='POSSE_TRAY_RECONCILIATION_REQUIRED');
  const current=(await f.motor.listPrepared({bridgeId:BRIDGE},f.context))[0].conformitat;assert.equal(current.state,'indeterminate');
  await assert.rejects(f.motor.publish(f.ref(current.head),f.context));assert.equal(f.counts.publishes,1);
});

test('a committed intent with a lost local ACK blocks sends, and a committed completion is never demoted',async()=>{
  const f=await fixture(),p=await f.prepare(),a=await f.approve(p.conformitat);f.faults.committedAppend='dispatching';
  await assert.rejects(f.motor.publish(f.ref(a.head),f.context));assert.equal(f.counts.publishes,0);
  const held=(await f.motor.listPrepared({bridgeId:BRIDGE},f.context))[0].conformitat;assert.equal(held.state,'dispatching');
  await assert.rejects(f.motor.publish(f.ref(held.head),f.context));assert.equal(f.counts.publishes,0);
  const g=await fixture(),q=await g.prepare(),b=await g.approve(q.conformitat);g.faults.committedAppend='published';
  await assert.rejects(g.motor.publish(g.ref(b.head),g.context));assert.equal(g.counts.publishes,1);
  assert.equal((await g.motor.listPrepared({bridgeId:BRIDGE},g.context))[0].conformitat.state,'published');
});

test('missing withdrawal adapter refuses before intent; unverified ACK stays held without a Tombstone',async()=>{
  const f=await fixture({withdrawal:false}),published=await f.publish(),before=f.events.length;
  await assert.rejects(f.motor.preparaAprovacio({...f.ref(published.head),action:'revoke'},f.context),e=>e.code==='POSSE_TRAY_WITHDRAWAL_UNAVAILABLE');
  await assert.rejects(f.motor.revoca(f.ref(published.head),f.context),e=>e.code==='POSSE_TRAY_WITHDRAWAL_UNAVAILABLE');assert.equal(f.events.length,before);
  const g=await fixture(),p=await g.publish(),a=await g.approve(p,'revoke');g.faults.ack=true;
  await assert.rejects(g.motor.revoca(g.ref(a.head),g.context),e=>e.code==='POSSE_TRAY_RECONCILIATION_REQUIRED');
  const held=(await g.motor.listPrepared({bridgeId:BRIDGE},g.context))[0].conformitat;assert.equal(held.state,'indeterminate');assert.equal(held.tombstone,null);
});

test('cancel and session changes stop early, and late changes never expose a false confirmed state',async()=>{
  const f=await fixture(),p=await f.prepare(),a=await f.approve(p.conformitat),control=new AbortController();control.abort();
  await assert.rejects(f.motor.publish(f.ref(a.head),f.context,{signal:control.signal}),e=>e.name==='AbortError');assert.equal(f.counts.publishes,0);
  const original=f.journal.read;f.journal.read=async(...args)=>{const r=await original(...args);f.changeSession();return r;};
  await assert.rejects(f.motor.publish(f.ref(a.head),f.context),e=>e.name==='AbortError');assert.equal(f.counts.publishes,0);
  for(const mode of ['lateSession','lateCancel']){
    const g=await fixture(),q=await g.prepare(),b=await g.approve(q.conformitat),cancel=new AbortController();g.faults[mode]=mode==='lateSession'?true:cancel;
    await assert.rejects(g.motor.publish(g.ref(b.head),g.context,{signal:cancel.signal}),e=>e.code==='POSSE_TRAY_RECONCILIATION_REQUIRED');
    assert.equal(g.counts.publishes,1);assert.equal((await g.motor.listPrepared({bridgeId:BRIDGE},g.context))[0].conformitat.state,'indeterminate');
  }
});

test('media-pending is never published and continuation requires another signed approval',async()=>{
  const f=await fixture();f.faults.mediaPending=true;
  f.setSource({cover:{public:true,blobRef:'public/cover',sha256:hash(new Uint8Array([1,2,3])),mimeType:'image/png',bytes:3,alt:'Portada pública',thumbnailUrl:'https://socdepoble.org/media/cover.png'}});
  const pending=await f.publish();assert.equal(pending.state,'media-pending');assert.equal(pending.receipt,null);assert.equal(f.counts.publishes,0);
  await assert.rejects(f.motor.publish(f.ref(pending.head),f.context),e=>e.code==='POSSE_TRAY_APPROVAL_REQUIRED');
  const approval=await f.approve(pending);f.faults.mediaPending=false;
  assert.equal((await f.motor.publish(f.ref(approval.head),f.context)).state,'published');assert.equal(f.counts.publishes,1);
});

test('expired approval can be renewed, nonce reuse is refused, and slow durable intent cannot outlive expiry or key revocation',async()=>{
  const f=await fixture(),p=await f.prepare(),a=await f.approve(p.conformitat);
  f.setTime(AT+120000);await assert.rejects(f.motor.publish(f.ref(a.head),f.context),e=>e.code==='POSSE_TRAY_APPROVAL_INVALID');assert.equal(f.counts.publishes,0);
  const renewed=await f.approve(a);assert.equal((await f.motor.publish(f.ref(renewed.head),f.context)).state,'published');
  for(const field of ['expireOnIntent','revokeOnIntent']){
    const g=await fixture(),q=await g.prepare(),b=await g.approve(q.conformitat);g.faults[field]=true;
    await assert.rejects(g.motor.publish(g.ref(b.head),g.context),e=>e.code==='POSSE_TRAY_RECONCILIATION_REQUIRED');assert.equal(g.counts.publishes,0);
  }
  const g=await fixture(),q=await g.prepare(),b=await g.approve(q.conformitat);
  const row=[...g.journals.values()][0].at(-1),request=await g.motor.preparaAprovacio({...g.ref(b.head),action:'publish'},g.context);
  const replay={...request.registre,nonce:row.approval.nonce};
  await assert.rejects(g.motor.aprova({...g.ref(b.head),action:'publish',aprovacio:await g.sign(replay)},g.context),e=>e.code==='POSSE_TRAY_NONCE_REPLAY');assert.equal(g.counts.publishes,0);
});

for(const mode of ['expiry','session','key','cancel'])test(`independent regression: ${mode} during raw preflight/claim/marker blocks the first external status or media write`,async()=>{
  for(const invalidAt of ['preflight','claim','marker:status-post','media-read','marker:media-post']){
    const f=await fixture();
    if(invalidAt.includes('media'))f.setSource({cover:{public:true,blobRef:'public/cover',sha256:hash(new Uint8Array([1,2,3])),mimeType:'image/png',bytes:3,alt:'Portada pública',thumbnailUrl:'https://socdepoble.org/media/cover.png'}});
    const p=await f.prepare(),a=await f.approve(p.conformitat),control=new AbortController();
    Object.assign(f.faults,{invalidAt,invalidMode:mode,cancelControl:control});
    await assert.rejects(f.motor.publish(f.ref(a.head),f.context,{signal:control.signal}));
    assert.equal(f.counts.publishes,0,`${mode}/${invalidAt}: status not permitted`);
    assert.equal(f.counts.uploads,0,`${mode}/${invalidAt}: media not permitted`);
  }
});

test('independent regression: a pending new draft can revoke the prior published binding without approving the new body',async()=>{
  const f=await fixture(),published=await f.publish(),binding=clone(published.binding);
  f.setSource({recordRevision:'2',title:'Cos nou encara no aprovat'});
  const pending=await f.prepare();assert.equal(pending.conformitat.state,'prepared');assert.ok(pending.conformitat.receipt);
  const approval=await f.approve(pending.conformitat,'revoke');assert.deepEqual(approval.binding,binding);
  const revoked=await f.motor.revoca(f.ref(approval.head),f.context);assert.equal(revoked.state,'revoked');
  assert.deepEqual(revoked.binding,binding);assert.equal(f.counts.publishes,1);assert.equal(f.counts.withdraws,1);
});
